  const parse = (block) =>
    block.trim().split('\n').map((line, i) => {
      const cut = line.indexOf('|');
      return { n: i + 1, ref: line.slice(0, cut).trim(), text: line.slice(cut + 1).trim() };
    });

  root.VERSE_DATA = { en: parse(EN), ta: parse(TA), te: parse(TE) };
